eleases":[{"zone":"PAL","national":null,"edition":"standard","title":"Ruby & Rusty – Save the Crows","dates":[{"region":"europe","date":"2022-01-01","precision":"year"}],"publishers":["name:bitmapsoft"]}]},{"qid":null,"title":"Pineapple Kid","title_merge":true,"first_release":{"date":"2021-01-01","precision":"year"},"developers":["name:mhzgames"],"releases":[{"zone":"PAL","national":null,"edition":"standard","title":"Pineapple Kid","dates":[{"region":"europe","date":"2021-01-01","precision":"year"}],"publishers":["name:bitmapsoft"]}]},{"qid":null,"title":"Tales of Monsterland","title_merge":true,"first_release":{"date":"2021-01-01","precision":"year"},"developers":["name:joeljarman"],"releases":[{"zone":"PAL","national":null,"edition":"standard","title":"Tales of Monsterland","dates":[{"region":"europe","date":"2021-01-01","precision":"year"}],"publishers":["name:bitmapsoft"]}]},{"qid":null,"title":"Magic Life Counter","title_merge":true,"first_release":{"date":"2026-01-01","precision":"year"},"developers":["name:falktattoos"],"releases":[{"zone":"NTSC-U","national":null,"edition":"standard","title":"Magic Life Counter","dates":[{"region":"north-america","date":"2026-01-01","precision":"year"}],"publishers":["name:falktattoos"]}]},{"qid":null,"title":"Shadow Island","title_merge":true,"first_release":{"date":"2026-01-01","precision":"year"},"developers":["name:daveygreenman"],"releases":[{"zone":"NTSC-U","national":null,"edition":"standard","title":"Shadow Island","dates":[{"region":"north-america","date":"2026-01-01","precision":"year"}],"publishers":["name:daveygreenman"]}]},{"qid":null,"title":"Triple Threat Terror","title_merge":true,"first_release":{"date":"2025-01-01","precision":"year"},"developers":["name:goncalofernandes"],"releases":[{"zone":"NTSC-U","national":null,"edition":"standard","title":"Triple Threat Terror","dates":[{"region":"north-america","date":"2025-01-01","precision":"year"}],"publishers":["name:goncalofernandes"]}]},{"qid":null,"title":"Land of the Free","title_merge":true,"first_release":{"date":"2026-01-01","precision":"year"},"developers":["name:goncalofernandes"],"releases":[{"zone":"NTSC-U","national":null,"edition":"standard","title":"Land of the Free","dates":[{"region":"north-america","date":"2026-01-01","precision":"year"}],"publishers":["name:goncalofernandes"]}]},{"qid":null,"title":"Cel Story","title_merge":true,"first_release":{"date":"2024-01-01","precision":"year"},"developers":["name:cel"],"releases":[{"zone":"PAL","national":null,"edition":"standard","title":"Cel Story","dates":[{"region":"europe","date":"2024-01-01","precision":"year"}],"publishers":["name:phoenixware"]}]},{"qid":null,"title":"COMMODORE 16+4 PACK FOR GAME BOY DMG","title_merge":true,"first_release":{"date":"2024-01-01","precision":"year"},"developers":["name:laszlorajcsanyi"],"releases":[{"zone":"NTSC-U","national":null,"edition":"standard","title":"COMMODORE 16+4 PACK FOR GAME BOY DMG","dates":[{"region":"north-america","date":"2024-01-01","precision":"year"}],"publishers":["name:insidegadgets"]}]}]}$wikipedia$::jsonb;
  v_platform bigint := (select id from public.platform where short_name = 'GB');
  company   jsonb;
  g         jsonb;
  r         jsonb;
  d         jsonb;
  k         text;
  v_game    bigint;
  v_release bigint;
  v_pal     bigint;
  v_zone    public.video_zone;
  companies jsonb := '{}';
begin
  -- Les jeux déjà sur cette console (import Wikidata), par clé de titre souple : un jeu de la
  -- liste sans lien Wikidata qui n'a pas trouvé son titre exact s'y raccroche
  create temp table loose_game on commit drop as
    select distinct r.game_id, pg_temp.loose_key(t.title) as k
    from public.release r
    join public.game x on x.id = r.game_id
    cross join lateral (values (x.title), (r.local_title)) as t (title)
    where r.platform_id = v_platform and t.title is not null;

  -- 1. Sociétés
  for company in select value from jsonb_array_elements(data -> 'companies') loop
    companies := companies || jsonb_build_object(
      company ->> 'key', pg_temp.company_id(company ->> 'qid', company ->> 'name'));
  end loop;

  for g in select value from jsonb_array_elements(data -> 'games') loop
    -- 2. Jeu : par identifiant Wikidata, sinon par titre normalisé, sinon création
    v_game := null;
    if g ->> 'qid' is not null then
      select id into v_game from public.game where wikidata_id = g ->> 'qid';
    end if;
    -- (par titre : jamais un jeu présent seulement sur une autre console, souvent une autre
    -- œuvre du même nom ; un jeu qui a déjà une version sur cette console, oui)
    if v_game is null and (g ->> 'title_merge')::boolean then
      select id into v_game from public.game x
      where x.title_key = public.normalize_name(g ->> 'title')
        and (x.wikidata_id is null or g ->> 'qid' is null)
        and (exists (select 1 from public.release o where o.game_id = x.id and o.platform_id = v_platform)
             or not exists (select 1 from public.release o where o.game_id = x.id and o.platform_id <> v_platform))
      order by exists (select 1 from public.release o where o.game_id = x.id and o.platform_id = v_platform) desc, x.id
      limit 1;
      if v_game is not null and g ->> 'qid' is not null then
        update public.game set wikidata_id = g ->> 'qid' where id = v_game;
      end if;
    end if;
    -- Titre exact introuvable : un jeu déjà sur cette console dont le titre correspond, en plus
    -- souple, au titre de la ligne ou à l'un de ses titres par zone (Lock On / Super Air Diver).
    -- Avec un lien Wikidata, seulement un jeu qui n'a ici qu'une version « à compléter » :
    -- Wikidata range parfois le même jeu sous deux éléments (Super Castles, Wrecking Crew '98),
    -- et celui que la liste n'a pas confirmé est le même jeu, pas un autre
    if v_game is null and (g ->> 'title_merge')::boolean then
      select l.game_id into v_game from loose_game l
      where l.k in (select pg_temp.loose_key(t.title) from (
              select g ->> 'title' union select x ->> 'title' from jsonb_array_elements(g -> 'releases') as x
            ) as t (title))
        and (g ->> 'qid' is null
             or not exists (select 1 from public.release o
                            where o.game_id = l.game_id and o.platform_id = v_platform and o.zone is not null))
      order by l.game_id
      limit 1;
    end if;
    if v_game is null then
      insert into public.game (title, wikidata_id)
      values (g ->> 'title', g ->> 'qid')
      returning id into v_game;
    end if;

    if g -> 'first_release' <> 'null'::jsonb then
      update public.game
      set first_release_date = (g -> 'first_release' ->> 'date')::date,
          first_release_precision = (g -> 'first_release' ->> 'precision')::public.date_precision
      where id = v_game and first_release_date is null;
    end if;

    for k in select jsonb_array_elements_text(g -> 'developers') loop
      insert into public.game_developer (game_id, company_id)
      values (v_game, (companies ->> k)::bigint)
      on conflict do nothing;
    end loop;

    -- 3. Sorties
    v_pal := null;
    for r in select value from jsonb_array_elements(g -> 'releases') loop
      v_zone := (r ->> 'zone')::public.video_zone;
      v_release := null;

      if r ->> 'edition' = 'platinum' then
        select id into v_release from public.release
        where game_id = v_game and platform_id = v_platform and zone = 'PAL'
          and edition_type = 'reissue' and edition_name = 'Platinum'
        order by id limit 1;
        if v_release is null then
          insert into public.release (game_id, platform_id, reissue_of, local_title, zone, edition_type, edition_name)
          values (v_game, v_platform, v_pal, r ->> 'title', 'PAL', 'reissue', 'Platinum')
          returning id into v_release;
        end if;

      elsif r ->> 'national' is not null then
        select id into v_release from public.release
        where game_id = v_game and platform_id = v_platform and zone = v_zone
          and edition_type = 'standard'
          and public.normalize_name(local_title) = public.normalize_name(r ->> 'title')
        order by id limit 1;
        if v_release is null then
          insert into public.release (game_id, platform_id, local_title, zone)
          values (v_game, v_platform, r ->> 'title', v_zone)
          returning id into v_release;
        end if;

      else
        -- Sortie de base de la zone : existante, ou sortie « à compléter » à réutiliser
        select id into v_release from public.release
        where game_id = v_game and platform_id = v_platform and zone = v_zone and edition_type = 'standard'
        order by id limit 1;
        if v_release is null then
          select rel.id into v_release from public.release rel
          where rel.game_id = v_game and rel.platform_id = v_platform and rel.zone is null
            and rel.edition_type = 'standard' and rel.product_code is null
            and not exists (select 1 from public.collection_item ci where ci.release_id = rel.id)
            and not exists (select 1 from public.image i where i.release_id = rel.id)
          order by rel.id limit 1;
          if v_release is not null then
            update public.release set zone = v_zone, local_title = r ->> 'title' where id = v_release;
          else
            insert into public.release (game_id, platform_id, local_title, zone)
            values (v_game, v_platform, r ->> 'title', v_zone)
            returning id into v_release;
          end if;
        end if;
        if v_zone = 'PAL' then v_pal := v_release; end if;
      end if;

      for d in select value from jsonb_array_elements(r -> 'dates') loop
        insert into public.release_region (release_id, region_id, release_date, date_precision)
        select v_release, rg.id, (d ->> 'date')::date, (d ->> 'precision')::public.date_precision
        from public.region rg where rg.code = d ->> 'region'
        on conflict do nothing;
      end loop;

      for k in select jsonb_array_elements_text(r -> 'publishers') loop
        insert into public.release_company (release_id, company_id, role)
        values (v_release, (companies ->> k)::bigint, 'publisher')
        on conflict do nothing;
      end loop;
    end loop;
  end loop;
end;
$import$;

drop function pg_temp.company_id(text, text);
drop function pg_temp.loose_key(text);
